  group('startupApiKey', () {
    final entry = CustomProviderEntry(
      name: 'mine',
      apiType: 'openai',
      baseUrl: 'http://llama.local:8080',
      modelId: 'm1',
      keyName: 'ENTRY_KEY',
    );

    test('an interactive start tolerates a missing key', () {
      final key = startupApiKey(
        'openai-completions',
        SecureKeyCache(null),
