    });

    test('a headless hosted start with an env key resolves it', () {
      final key = startupApiKey(
        'openai-completions',
        SecureKeyCache(null),
        baseUrl: _openrouter,
        customProviders: const [],
        defaultRoleResolved: false,
        interactive: false,
        env: const {'OPENROUTER_API_KEY': 'envkeyvalue123'},
