        customProviders: [
          CustomProviderEntry(
            name: 'keyless',
            apiType: 'openai',
            baseUrl: 'http://llama.local:8080',
            modelId: 'm1',
          ),
        ],
        defaultRoleResolved: false,
        interactive: false,
        env: const {},
      );
      expect(key, isEmpty);
    });

    test('a name-scoped custom entry key resolves from the store', () async {
      final key = startupApiKey(
        'openai-completions',
        await _cache({'ENTRY_KEY': 'storekeyvalue'}),
        baseUrl: 'http://llama.local:8080',
        customProviders: [entry],
