    expect(saved.customProviders.single.baseUrl, mockUrl);
    final parsed = parseCliArgs(['-p', 'hi']) as CliArgs;
    final effective = resolveEffectiveCliArgs(parsed, saved);
    expect(effective.provider, 'openai-completions');
